def carry_preview_plans(here):
    """One time, after the edits: carry each plan the preview made into
    data/path_plans.json under the spacecraft's new key, when it was made
    from exactly what the keyed entry plans from now, by the orbiter rule
    (its inputs_sha256 matches). Then remove the preview's file. Returns
    the lines to print. Never fails the patch: a plan not carried is made
    by the Path Plan itself."""
    import importlib
    import json
    import re
    sys.path.insert(0, here)
    preview = os.path.join(here, "data", "path_plans_preview.json")
    if not os.path.exists(preview):
        return ["note: data/path_plans_preview.json is not here, so no plan "
                "was carried; press Path Plan -- every path, now on the "
                "dashboard"]
    try:
        pp = importlib.import_module("path_plan")
        with open(os.path.join(here, "celestial_objects.py"), "r",
                  encoding="utf-8") as handle:
            entries = pp.keyed_entries(handle.read())
        bodies = pp.searched_bodies(entries)
        with open(preview, "r", encoding="utf-8") as handle:
            old = json.load(handle).get("plans") or {}
        target = os.path.join(here, pp.PLANS)
        plans = {}
        if os.path.exists(target):
            with open(target, "r", encoding="utf-8") as handle:
                plans = json.load(handle).get("plans") or {}
    except Exception as exc:          # the edits stand; the plan is remade
        return ["note: the preview's plans could not be read (%s); none "
                "carried. Press Path Plan -- every path, now" % exc]
    carried, refused = [], []
    for f in entries:
        if not pp.is_spacecraft(f):
            continue
        was = "preview_" + re.sub(r"[^a-z0-9]+", "_",
                                  f["name"].lower()).strip("_")
        plan = old.get(was)
        if plan is None:
            refused.append("%s (no preview plan)" % f["key"])
            continue
        want = pp.inputs_sha256(pp.plan_inputs(f, bodies))
        if plan.get("inputs_sha256") != want:
            refused.append("%s (its preview plan was made by another rule "
                           "or from other inputs)" % f["key"])
            continue
        plans[f["key"]] = plan
        carried.append("%s %d events" % (f["key"], len(plan["events"])))
    lines = []
    if carried:
        pp.write_plans(target, plans)
        lines.append("ok  data/path_plans.json: carried from the preview: "
                     + ", ".join(carried))
    if refused:
        lines.append("note: NOT carried, so the Path Plan makes them: "
                     + "; ".join(refused) + ". Press Path Plan -- every "
                     "path, now on the dashboard before the maintenance run")
    if carried and not refused:
        os.remove(preview)
        lines.append("ok  data/path_plans_preview.json: removed (every plan "
                     "in it carried)")
    elif carried:
        lines.append("note: data/path_plans_preview.json kept, as not "
                     "every plan in it was carried")
    return lines


def fail(msg):
    print(msg)
    print("NOTHING was written. Undo is not needed.")
    sys.exit(1)


def main():
    for rel, _ in NEW_FILES:
        if os.path.exists(os.path.join(HERE, *rel.split("/"))):
            fail("ERROR: %s already exists; this patch has run." % rel)
    staged = []
    for rel, edits in EDITS:
        path = os.path.join(HERE, *rel.split("/"))
        if not os.path.isfile(path):
            fail("ERROR: not found: %s -- is this file in the right folder?"
                 % path)
        raw = open(path, "rb").read()
        crlf = b"\r\n" in raw
        text = raw.replace(b"\r\n", b"\n").decode("utf-8")
        if SENTINELS.get(rel) and SENTINELS[rel] in text:
            fail("ERROR: %s already carries this patch's change; this "
                 "patch has run." % rel)
        for k, (old, new) in enumerate(edits):
            n = text.count(old)
            if n != 1:
                if new and text.count(new) == 1 and old not in text:
                    fail("ERROR: %s already carries edit %d of %d; this "
                         "patch has run." % (rel, k + 1, len(edits)))
                fail("ANCHOR FAIL in %s, edit %d of %d: expected 1 match, "
                     "found %d" % (rel, k + 1, len(edits), n))
            text = text.replace(old, new)
        staged.append((rel, path, text, crlf, len(edits)))
    for rel, path, text, crlf, n in staged:
        open(path, "wb").write(text.encode("utf-8"))
        print("ok  %s (%d edits)" % (rel, n))
        if crlf:
            print("note: %s was CRLF in the working copy; written LF" % rel)
        bad = sum(1 for c in text if ord(c) > 127)
        if bad:
            print("note: %s holds %d non-ASCII character(s) this patch did "
                  "not add" % (rel, bad))
    for rel, content in NEW_FILES:
        full = os.path.join(HERE, *rel.split("/"))
        d = os.path.dirname(full)
        if d and not os.path.isdir(d):
            os.makedirs(d)
        open(full, "wb").write(content.encode("utf-8"))
        print("ok  %s: new" % rel)
    for name in POST_CALLS:
        for line in globals()[name](HERE):
            print(line)
    print(DONE % (len(staged), len(NEW_FILES)))


if __name__ == "__main__":
    main()
